
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_lkt_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_lkt", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.045091775752370e+02, 1.008796193090949e+02, 9.592000953812534e+01, 8.929408846554514e+01, 8.072485687727196e+01, 7.014887342636609e+01, 5.794794360281627e+01, 4.517821667551217e+01, 3.350920452859041e+01, 2.399626407262865e+01, 1.321609623329400e+01, 3.128850610288579e+00, 2.035168851958962e+00, 1.546570432637448e+00, 1.076435196904386e+00, 8.068633505024057e-01, 7.082292641904282e-01, 6.482679847853012e-01, 6.034971624558374e-01, 5.743491734340817e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


